package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.EmailVerifiedVO;

class EmailVerifiedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of email verified of user")
  void test_email_verified_value_holder_assign_plain_value() {
    Object holder = new Object();
    EmailVerifiedValueHolder<Object> value = new EmailVerifiedValueHolder<>(holder);
    Assertions.assertSame(holder, value.emailVerified(true), "Setters must return the holder");
    Assertions.assertTrue(value.getEmailVerifiedValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getEmailVerified().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.emailVerifiedNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getEmailVerifiedValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of email verified of user")
  void test_email_verified_value_holder_assign_value_object() {
    Object holder = new Object();
    EmailVerifiedValueHolder<Object> value = new EmailVerifiedValueHolder<>(holder);
    EmailVerifiedVO vo = EmailVerifiedVO.from(true);
    Assertions.assertFalse(value.getEmailVerifiedValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.emailVerified(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getEmailVerifiedValue().orElseThrow());
    Assertions.assertSame(holder, value.emailVerified(Optional.empty()));
    Assertions.assertFalse(value.getEmailVerifiedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.emailVerified(Optional.of(vo)));
    Assertions.assertSame(vo, value.getEmailVerifiedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of email verified of user against the original")
  void test_email_verified_value_holder_read() {
    Object holder = new Object();
    EmailVerifiedValueHolder<Object> value = new EmailVerifiedValueHolder<>(holder);
    EmailVerifiedVO vo = EmailVerifiedVO.from(true);
    EmailVerifiedVO other = EmailVerifiedVO.from(true);
    User original = Mockito.mock(User.class);
    Mockito.when(original.getEmailVerifiedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readEmailVerified(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readEmailVerified(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.emailVerified(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readEmailVerified(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readEmailVerified(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of email verified of user")
  void test_email_verified_value_holder_unset() {
    Object holder = new Object();
    EmailVerifiedValueHolder<Object> value = new EmailVerifiedValueHolder<>(holder);
    EmailVerifiedVO vo = EmailVerifiedVO.from(true);
    value.emailVerified(vo);
    Assertions.assertSame(holder, value.unsetEmailVerifiedIfMatches("emailVerified_other"));
    Assertions.assertTrue(value.getEmailVerifiedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetEmailVerifiedIfMatches("emailVerified"));
    Assertions.assertFalse(value.getEmailVerifiedValue().isPresent(),
        "The field name must clear the value");
    value.emailVerified(vo);
    Assertions.assertSame(holder, value.unsetEmailVerified());
    Assertions.assertFalse(value.getEmailVerifiedValue().isPresent(), "Unset must clear the value");
  }
}
